SELECT DISTINCT le.lootdrop_id, 36641, 1, 0, 8 FROM npc_types n
JOIN loottable_entries le ON le.loottable_id = n.loottable_id
WHERE n.id IN (436014,436017,436019,436051,436084,436089,436121,436161) AND n.loottable_id > 0 AND NOT EXISTS (SELECT 1 FROM lootdrop_entries de WHERE de.lootdrop_id = le.lootdrop_id AND de.item_id = 36641);

